window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c3e8bf6e850e865"]={"versions": [{"id": "FIG-7c3e8bf6e850e865", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Master-Ablaufs der CAN-Zeitsynchronisation (AUTOSAR Classic Platform, BSW-Modul CanTSyn). Das Diagramm spezifiziert das zweistufige Synchronisationsverfahren (2-Step Time Master mit SYNC- und FUP-Botschaften) im Zusammenspiel zwischen dem Synchronized Time-Base Manager (StbM), dem CAN Time Synchronization Modul (CanTSyn) und dem CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Lebenslinien / BSW-Module:</strong></p>\n<ul class=\"fig-list\"><li><code>«module» StbM</code>: Verwaltet die synchronisierte Zeitbasis sowie die Virtual Local Time (VLT).\n</li><li><code>«module» CanTSyn</code>: Steuert als Time Master die Generierung von SYNC- und FUP-Nachrichten sowie die Zeitstempelberechnung.\n</li><li><code>«module» CanIf</code>: CAN Interface zur Botschaftsübertragung und Bereitstellung der Tx-Bestätigung.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen &amp; Aufrufe:</strong></p>\n<ul class=\"fig-list\"><li><code>CanTSyn_MainFunction()</code>: Periodische Hauptfunktion des Moduls CanTSyn.\n</li><li><code>StbM_BusGetCurrentTime(Std_ReturnType, StbM_SynchronizedTimeBaseType, StbM_TimeStampType*, StbM_VirtualLocalTimeType*, StbM_UserDataType*)</code>: Synchroner Abruf der aktuellen globalen Zeit (<code>globalTimePtr</code>), der zugehörigen lokalen Zeit (<code>localTimePtr</code>) und Anwenderdaten.\n</li><li><code>CanIf_Transmit(SYNC)</code> / <code>CanIf_Transmit(FUP)</code>: Sendeaufrufe an CanIf für SYNC- und Follow-Up-PDUs.\n</li><li><code>CanTSyn_TxConfirmation(SYNC)</code>: Callback von CanIf an CanTSyn nach erfolgreichem Senden des SYNC-Frames.\n</li><li><code>StbM_GetCurrentVirtualLocalTime(StbM_SynchronizedTimeBaseType, StbM_VirtualLocalTimeType*): Std_ReturnType</code>: Synchroner Abruf der exakten virtuellen lokalen Zeit im Kontext der TxConfirmation.\n</li></ul>\n<p class=\"fig-p\"><strong>Parameter &amp; interne Variablen:</strong></p>\n<ul class=\"fig-list\"><li><code>T0SYNCns</code>: Nanosekundenanteil von <code>*globalTimePtr</code> zum Abtastzeitpunkt T0.\n</li><li><code>T0VLT</code>: Lokale Referenzzeit <code>*localTimePtr</code> zum Zeitpunkt T0.\n</li><li><code>T1VLT</code>: Lokale Zeit <code>*localTimePtr</code> zum Sendezeitpunkt T1.\n</li><li><code>T4</code>: Berechneter Sendezeitpunkt T4 = T0SYNCns + (T1VLT - T0VLT).\n</li><li><code>OVS</code>: Sekundenüberlauf (<code>second portion of T4</code>), bedingt durch <code>[T4 &gt;= 1s]</code>.\n</li><li><code>SyncTimeNSec</code>: Nanosekundenanteil von T4.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>SYNC-Initiierung:</strong>\n<ul class=\"fig-list\"><li>In <code>CanTSyn_MainFunction()</code> fragt CanTSyn über <code>StbM_BusGetCurrentTime(...)</code> die Zeitbasis ab und speichert intern <code>T0SYNCns</code> sowie <code>T0VLT</code>.\n</li><li>CanTSyn stößt via <code>CanIf_Transmit(SYNC)</code> das Senden der Synchronisationsbotschaft an.\n</li></ul>\n</li><li><strong>Sendezeitpunkterfassung via TxConfirmation:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreichem Bustransfer ruft CanIf den Callback <code>CanTSyn_TxConfirmation(SYNC)</code> auf.\n</li><li>CanTSyn ruft sofort <code>StbM_GetCurrentVirtualLocalTime(...)</code> auf und belegt <code>T1VLT</code>.\n</li><li>CanTSyn berechnet T4 = T0SYNCns + (T1VLT - T0VLT). Falls T4 ≥ 1\\,s, wird der Sekundenübertrag in <code>OVS</code> abgelegt; <code>SyncTimeNSec</code> erhält den verbleibenden Nanosekundenanteil.\n</li></ul>\n</li><li><strong>Follow-Up-Übertragung:</strong>\n<ul class=\"fig-list\"><li>Im nachfolgenden Aufruf von <code>CanTSyn_MainFunction()</code> wird per <code>CanIf_Transmit(FUP)</code> die Follow-Up-Botschaft mit den berechneten Zeitdaten (<code>SyncTimeNSec</code>, ggf. <code>OVS</code>) abgesetzt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Latenz- und Jitterminimierung (Hinweisbox):</strong>\n<ul class=\"fig-list\"><li><code>StbM_GetCurrentVirtualLocalTime()</code> muss zur Minimierung von Messfehlern so früh wie möglich in <code>CanTSyn_TxConfirmation()</code> aufgerufen werden.\n</li><li>Das System muss Unterbrechungen vom Beginn der TxIndication/TxConfirmation bis zur Rückkehr von <code>StbM_GetCurrentVirtualLocalTime()</code> unterbinden (kritischer Abschnitt).\n</li></ul>\n</li><li><strong>2-Step-Synchronisationsprinzip:</strong> Rechnerischer Ausgleich von Sende- und Busarbitrierungsverzögerungen über die nachgelagerte FUP-Nachricht, da Standard-CAN-Hardware keine Sendezeitstempel direkt im SYNC-Frame injizieren kann.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-523402c869503923", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Master-Ablaufs der CAN-Zeitsynchronisation (AUTOSAR Classic Platform, BSW-Modul CanTSyn). Das Diagramm spezifiziert das zweistufige Synchronisationsverfahren (2-Step Time Master mit SYNC- und FUP-Botschaften) im Zusammenspiel zwischen dem Synchronized Time-Base Manager (StbM), dem CAN Time Synchronization Modul (CanTSyn) und dem CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Lebenslinien / BSW-Module:</strong></p>\n<ul class=\"fig-list\"><li><code>«module» StbM</code>: Verwaltet Zeitbasen, Virtual Local Time und verarbeitet Master-Timing-Messdaten.\n</li><li><code>«module» CanTSyn</code>: Time Master, steuert SYNC/FUP-Protokoll, Zeitstempelkorrektur und Validierungsdatenerfassung.\n</li><li><code>«module» CanIf</code>: CAN Interface zur Übertragungsabwicklung.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen &amp; Aufrufe:</strong></p>\n<ul class=\"fig-list\"><li><code>CanTSyn_MainFunction()</code>: Periodische Hauptfunktion von CanTSyn.\n</li><li><code>StbM_BusGetCurrentTime(Std_ReturnType, StbM_SynchronizedTimeBaseType, StbM_TimeStampType*, StbM_VirtualLocalTimeType*, StbM_UserDataType*)</code>: Synchroner Abruf von Zeitbasis, VLT und User Data.\n</li><li><code>CanIf_Transmit(SYNC)</code> / <code>CanIf_Transmit(FUP)</code>: Sendeaufrufe für SYNC- und FUP-Frames.\n</li><li><code>CanTSyn_TxConfirmation(SYNC)</code>: Sendeerfolgs-Callback von CanIf.\n</li><li><code>StbM_GetCurrentVirtualLocalTime(StbM_SynchronizedTimeBaseType, StbM_VirtualLocalTimeType*): Std_ReturnType</code>: Synchroner VLT-Abruf in der TxConfirmation.\n</li><li><code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code>: Synchroner API-Aufruf zur Übergabe der Messdaten an StbM.\n</li></ul>\n<p class=\"fig-p\"><strong>Parameter, Datenstrukturen &amp; Variablen:</strong></p>\n<ul class=\"fig-list\"><li><code>T0SYNC</code>: Vollständiger globaler Zeitstempel <code>*globalTimePtr</code> zum Abtastzeitpunkt T0.\n</li><li><code>T0SYNCns</code>: Nanosekundenanteil von <code>*globalTimePtr</code>.\n</li><li><code>T0VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Zeitpunkt T0.\n</li><li><code>T1VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Sendezeitpunkt T1.\n</li><li><code>T4</code>: Korrigierter Sendezeitpunkt T4 = T0SYNCns + (T1VLT - T0VLT).\n</li><li><code>OVS</code>: Sekundenüberlauf (<code>second portion of T4</code>), bedingt durch <code>[T4 &gt;= 1s]</code>.\n</li><li><code>SyncTimeNSec</code>: Nanosekundenanteil von T4.\n</li><li><code>measurementData</code>: Struktur <code>{sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> für Time Validation.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>SYNC-Initiierung:</strong>\n<ul class=\"fig-list\"><li>In <code>CanTSyn_MainFunction()</code> fragt CanTSyn über <code>StbM_BusGetCurrentTime(...)</code> die Zeitbasis ab und speichert <code>T0SYNC</code> (<code>*globalTimePtr</code>), <code>T0SYNCns</code> sowie <code>T0VLT</code>.\n</li><li>CanTSyn sendet den SYNC-Frame über <code>CanIf_Transmit(SYNC)</code>.\n</li></ul>\n</li><li><strong>Sendezeitpunkterfassung via TxConfirmation:</strong>\n<ul class=\"fig-list\"><li>CanIf ruft <code>CanTSyn_TxConfirmation(SYNC)</code> auf.\n</li><li>CanTSyn liest unverzüglich via <code>StbM_GetCurrentVirtualLocalTime(...)</code> den Wert <code>T1VLT</code> aus.\n</li><li>Berechnung von T4 = T0SYNCns + (T1VLT - T0VLT), <code>OVS</code> (bei T4 ≥ 1\\,s) und <code>SyncTimeNSec</code>.\n</li></ul>\n</li><li><strong>FUP-Übertragung &amp; Time Validation:</strong>\n<ul class=\"fig-list\"><li>Im folgenden Zyklus von <code>CanTSyn_MainFunction()</code> wird <code>CanIf_Transmit(FUP)</code> aufgerufen.\n</li><li><strong>Kombiniertes Fragment <code>opt [Time Validation enabled]</code>:</strong>\n<ul class=\"fig-list\"><li>Bei aktivierter Zeitvalidierung bereitet CanTSyn <code>measurementData = {sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> vor.\n</li><li>Aufruf von <code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code> zur synchronen Weitergabe der Messdaten an StbM.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Latenz- und Jitterminimierung (Hinweisbox):</strong>\n<ul class=\"fig-list\"><li><code>StbM_GetCurrentVirtualLocalTime()</code> muss so früh wie möglich in <code>CanTSyn_TxConfirmation()</code> ausgeführt werden.\n</li><li>Unterbrechungen zwischen Beginn der TxIndication/TxConfirmation und Ende der VLT-Abfrage sind zwingend zu sperren.\n</li></ul>\n</li><li><strong>2-Step-Synchronisationsprinzip:</strong> Kompensation variabler Buszugriffsverzögerungen über den nachfolgenden FUP-Frame.\n</li><li><strong>Time Validation Unterstützung:</strong>\n<ul class=\"fig-list\"><li>Bei aktiver Validierungskonfiguration (<code>[Time Validation enabled]</code>) müssen die Master-Timing-Messdaten (Sequenzzähler, Sendezeitpunkt T1VLT und errechneter absoluter globaler Sendezeitstempel) erfasst und via <code>StbM_CanSetMasterTimingData</code> an StbM gemeldet werden.\n</li><li>Die Messdatenübergabe erfolgt synchron im Kontext von <code>CanTSyn_MainFunction()</code> unmittelbar nach Anstoßen der FUP-Übertragung.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-195cb4f037462b7c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Master-Ablaufs der CAN-Zeitsynchronisation (AUTOSAR Classic Platform, BSW-Modul CanTSyn). Das Diagramm spezifiziert das zweistufige Synchronisationsverfahren (2-Step Time Master mit SYNC- und FUP-Botschaften) im Zusammenspiel zwischen dem Synchronized Time-Base Manager (StbM), dem CAN Time Synchronization Modul (CanTSyn) und dem CAN Interface (CanIf).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Lebenslinien / BSW-Module:</strong></p>\n<ul class=\"fig-list\"><li><code>«module» StbM</code>: Verwaltet Zeitbasen, Virtual Local Time und verarbeitet Master-Timing-Messdaten.\n</li><li><code>«module» CanTSyn</code>: Time Master, steuert SYNC/FUP-Protokoll, Zeitstempelkorrektur und Validierungsdatenerfassung.\n</li><li><code>«module» CanIf</code>: CAN Interface zur Übertragungsabwicklung.\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen &amp; Aufrufe:</strong></p>\n<ul class=\"fig-list\"><li><code>CanTSyn_MainFunction()</code>: Periodische Hauptfunktion von CanTSyn.\n</li><li><code>StbM_BusGetCurrentTime(Std_ReturnType, StbM_SynchronizedTimeBaseType, StbM_TimeStampType*, StbM_VirtualLocalTimeType*, StbM_UserDataType*)</code>: Synchroner Abruf von Zeitbasis, VLT und User Data.\n</li><li><code>CanIf_Transmit(SYNC)</code> / <code>CanIf_Transmit(FUP)</code>: Sendeaufrufe für SYNC- und FUP-Frames.\n</li><li><code>CanTSyn_TxConfirmation(SYNC)</code>: Sendeerfolgs-Callback von CanIf.\n</li><li><code>StbM_GetCurrentVirtualLocalTime(StbM_SynchronizedTimeBaseType, StbM_VirtualLocalTimeType*): Std_ReturnType</code>: Synchroner VLT-Abruf in der TxConfirmation.\n</li><li><code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code>: Synchroner API-Aufruf zur Übergabe der Messdaten an StbM.\n</li></ul>\n<p class=\"fig-p\"><strong>Parameter, Datenstrukturen &amp; Variablen:</strong></p>\n<ul class=\"fig-list\"><li><code>T0SYNC</code>: Vollständiger globaler Zeitstempel <code>*globalTimePtr</code> zum Abtastzeitpunkt T0.\n</li><li><code>T0SYNCns</code>: Nanosekundenanteil von <code>*globalTimePtr</code>.\n</li><li><code>T0VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Zeitpunkt T0.\n</li><li><code>T1VLT</code>: Virtuelle lokale Zeit <code>*localTimePtr</code> zum Sendezeitpunkt T1.\n</li><li><code>T4</code>: Korrigierter Sendezeitpunkt T4 = T0SYNCns + (T1VLT - T0VLT).\n</li><li><code>OVS</code>: Sekundenüberlauf (<code>second portion of T4</code>), bedingt durch <code>[T4 &gt;= 1s]</code>.\n</li><li><code>SyncTimeNSec</code>: Nanosekundenanteil von T4.\n</li><li><code>measurementData</code>: Struktur <code>{sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> für Time Validation.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>SYNC-Initiierung:</strong>\n<ul class=\"fig-list\"><li>In <code>CanTSyn_MainFunction()</code> fragt CanTSyn über <code>StbM_BusGetCurrentTime(...)</code> die Zeitbasis ab und speichert <code>T0SYNC</code> (<code>*globalTimePtr</code>), <code>T0SYNCns</code> sowie <code>T0VLT</code>.\n</li><li>CanTSyn sendet den SYNC-Frame über <code>CanIf_Transmit(SYNC)</code>.\n</li></ul>\n</li><li><strong>Sendezeitpunkterfassung via TxConfirmation:</strong>\n<ul class=\"fig-list\"><li>CanIf ruft <code>CanTSyn_TxConfirmation(SYNC)</code> auf.\n</li><li>CanTSyn liest unverzüglich via <code>StbM_GetCurrentVirtualLocalTime(...)</code> den Wert <code>T1VLT</code> aus.\n</li><li>Berechnung von T4 = T0SYNCns + (T1VLT - T0VLT), <code>OVS</code> (bei T4 ≥ 1\\,s) und <code>SyncTimeNSec</code>.\n</li></ul>\n</li><li><strong>FUP-Übertragung &amp; Time Validation:</strong>\n<ul class=\"fig-list\"><li>Im folgenden Zyklus von <code>CanTSyn_MainFunction()</code> wird <code>CanIf_Transmit(FUP)</code> aufgerufen.\n</li><li><strong>Kombiniertes Fragment <code>opt [Time Validation enabled]</code>:</strong>\n<ul class=\"fig-list\"><li>Bei aktivierter Zeitvalidierung bereitet CanTSyn <code>measurementData = {sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> vor.\n</li><li>Aufruf von <code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code> zur synchronen Weitergabe der Messdaten an StbM.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Latenz- und Jitterminimierung (Hinweisbox):</strong>\n<ul class=\"fig-list\"><li><code>StbM_GetCurrentVirtualLocalTime()</code> muss so früh wie möglich in <code>CanTSyn_TxConfirmation()</code> ausgeführt werden.\n</li><li>Unterbrechungen zwischen Beginn der TxIndication/TxConfirmation und Ende der VLT-Abfrage sind zwingend zu sperren.\n</li></ul>\n</li><li><strong>2-Step-Synchronisationsprinzip:</strong> Kompensation variabler Buszugriffsverzögerungen über den nachfolgenden FUP-Frame.\n</li><li><strong>Time Validation Unterstützung:</strong>\n<ul class=\"fig-list\"><li>Bei aktiver Validierungskonfiguration (<code>[Time Validation enabled]</code>) müssen die Master-Timing-Messdaten (Sequenzzähler, Sendezeitpunkt T1VLT und errechneter absoluter globaler Sendezeitstempel) erfasst und via <code>StbM_CanSetMasterTimingData</code> an StbM gemeldet werden.\n</li><li>Die Messdatenübergabe erfolgt synchron im Kontext von <code>CanTSyn_MainFunction()</code> unmittelbar nach Anstoßen der FUP-Übertragung.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7c3e8bf6e850e865", "to": "FIG-523402c869503923", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung des Interaktionsfragments <code>opt [Time Validation enabled]</code> am Ende des Ablaufs in <code>CanTSyn_MainFunction()</code>.\n</li><li>Neuer synchroner API-Aufruf <code>StbM_CanSetMasterTimingData(timeBaseId, &amp;measurementData)</code> von <code>CanTSyn</code> an <code>StbM</code>.\n</li><li>Einführung der Datenstruktur <code>measurementData = {sequenceCounter, T1vlt, T0SYNC + (T1VLT - T0VLT)}</code> in <code>CanTSyn</code>.\n</li><li>Erweiterung der internen Variablenbelegung nach <code>StbM_BusGetCurrentTime</code>: Speicherung von <code>T0SYNC = *globalTimePtr</code> zusätzlich zu <code>T0SYNCns</code>.\n</li></ul>"}, {"from": "FIG-523402c869503923", "to": "FIG-195cb4f037462b7c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
